-- Carga desde dataset_ventas_retail.xlsx del curso.
-- Se excluyen 20 filas sin Cantidad y 10 sin MontoTotal (sin solapamiento).
-- Se conservan TransactionID repetidos: corresponden a filas diferentes.
-- IdRegistroVenta: indice desde 1 despues del filtro, en orden del Excel.
-- Ejecutar sobre las tres tablas vacias creadas para el proyecto.
USE Retail_Final_DB;
GO
SET XACT_ABORT ON;
SET NOCOUNT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    IF EXISTS (SELECT 1 FROM dbo.clientes) OR EXISTS (SELECT 1 FROM dbo.productos) OR EXISTS (SELECT 1 FROM dbo.ventas)
