SELECT COUNT(*) AS cantidad_ventas, SUM(MontoTotal) AS total_ventas,
       MIN(FechaCompra) AS primera_venta, MAX(FechaCompra) AS ultima_venta
FROM dbo.ventas;
SELECT COUNT(*) AS cantidad_clientes FROM dbo.clientes;
SELECT COUNT(*) AS cantidad_productos FROM dbo.productos;
